{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is the average cost of book design?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Book design costs depend on what you need, eBook covers, print wraparound designs, or illustrated children's books all have different pricing. Simple eBook covers are more affordable, while print books requiring spine and back cover design cost more due to additional complexity. Children's books with custom illustrations represent the highest investment because of extensive artistic work. We don't use one-size-fits-all pricing because every book has unique requirements. During your free consultation, we'll discuss your specific project and provide a detailed, transparent quote showing exactly what's included, design concepts, revision rounds, final files, and any extras. No hidden fees, just honest pricing reflecting the actual work your book needs."
      }
    },
    {
      "@type": "Question",
      "name": "How much does an illustrator charge for a book?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Illustration costs vary based on style complexity, number of illustrations needed, detail level, and whether you need full-page artwork or spot illustrations. A 32-page picture book requiring 15-20 full-color illustrations costs significantly more than a chapter book needing just a few simple spot illustrations. Custom illustration is skilled artistic work that takes time, rushing or underpaying usually means disappointing results. We provide customised quotes after understanding your book's specific needs, preferred illustration style, and timeline. During consultation, we'll show style examples, discuss your vision, and provide transparent pricing. You'll know exactly what you're paying for and what illustration quality to expect before committing to anything."
      }
    },
    {
      "@type": "Question",
      "name": "How do I get someone to illustrate a book?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Getting your book illustrated through us is simple. Submit your manuscript or concept via our website with details about your illustration needs, full picture book illustrations, chapter book spots, or cover artwork. Include style preferences, character descriptions, and budget. We'll review within 48 hours and match you with an illustrator whose style suits your book. You'll see their portfolio before starting. The process includes concept sketches for approval, detailed illustration with ongoing feedback, revisions until satisfied, and final file delivery. We coordinate everything, you just provide input and approve work. No complicated agent negotiations or unclear processes, just straightforward professional illustration services."
      }
    },
    {
      "@type": "Question",
      "name": "How much does an illustration agent cost?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We're not an illustration agent, we provide illustration services directly without agent fees or commission percentages. You pay for the actual illustration work, not representation fees. Our project management is included in illustration costs, covering coordination between you and illustrators, timeline management, quality control, and final file delivery. This approach gives you professional illustration with expert coordination at lower costs than traditional agent representation. During consultation, we'll explain exactly what you're paying for, illustration work itself, included revisions, project coordination, and file delivery. Everything is transparent with no percentage-based fees or hidden agent commissions. Just straightforward pricing for professional illustration services."
      }
    },
    {
      "@type": "Question",
      "name": "How long does it take to illustrate a 32-page children's book?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Illustrating a 32-page picture book typically takes 6-10 weeks depending on style complexity and revisions. The timeline includes initial concept sketches (1-2 weeks), your feedback and approval, detailed illustration creation for all pages (3-5 weeks), revision rounds (1-2 weeks), and final file preparation (1 week). Complex, detailed styles take longer than simpler illustrations. Extensive revisions extend timelines accordingly. We provide realistic schedules during consultation based on your chosen style and book requirements. Rush services are available for tighter deadlines without compromising quality. Throughout the process, you'll receive regular updates and preview batches of illustrations, ensuring the final book matches your vision perfectly."
      }
    }
  ]
}

